CREATE TABLE calendar_events (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    source TEXT NOT NULL DEFAULT 'investing',
    country TEXT NOT NULL,
    currency TEXT,
    event_name TEXT NOT NULL,
    importance INTEGER,
    released_at TEXT NOT NULL,
    period_date TEXT,
    period_label TEXT,
    actual REAL,
    forecast REAL,
    previous REAL,
    raw_actual TEXT,
    raw_forecast TEXT,
    raw_previous TEXT,
    metric_id TEXT,
    dump_file TEXT,
    imported_at TEXT NOT NULL,
    UNIQUE(source, country, event_name, released_at)
  );
CREATE TABLE ingest_runs (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    started_at TEXT NOT NULL,
    finished_at TEXT,
    mode TEXT NOT NULL,
    status TEXT NOT NULL,
    metrics_processed INTEGER DEFAULT 0,
    observations_upserted INTEGER DEFAULT 0,
    error TEXT
  );
CREATE TABLE metrics (
    id TEXT PRIMARY KEY,
    region TEXT NOT NULL,
    category TEXT NOT NULL,
    subcategory TEXT NOT NULL,
    name TEXT NOT NULL,
    short_name TEXT NOT NULL,
    description TEXT NOT NULL,
    source TEXT NOT NULL,
    series_id TEXT NOT NULL,
    transform TEXT NOT NULL,
    frequency TEXT NOT NULL,
    unit TEXT NOT NULL,
    importance TEXT NOT NULL,
    official_url TEXT NOT NULL,
    docs_url TEXT NOT NULL,
    release_name TEXT NOT NULL,
    earliest_available TEXT,
    last_ingested_at TEXT,
    observation_count INTEGER DEFAULT 0
  );
CREATE TABLE observations (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    metric_id TEXT NOT NULL,
    date TEXT NOT NULL,
    value REAL NOT NULL,
    raw_value REAL,
    released_at TEXT,
    vintage_date TEXT,
    is_latest INTEGER DEFAULT 1,
    UNIQUE(metric_id, date, vintage_date)
  );
CREATE TABLE release_dispatch_state (
          metric_id TEXT NOT NULL,
          scheduled_at TEXT NOT NULL,
          status TEXT NOT NULL DEFAULT 'retry',
          attempts INTEGER NOT NULL DEFAULT 0,
          last_attempt_at TEXT,
          processed_at TEXT,
          last_error TEXT,
          PRIMARY KEY(metric_id, scheduled_at)
        );
CREATE TABLE releases (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    metric_id TEXT NOT NULL,
    period_date TEXT NOT NULL,
    released_at TEXT NOT NULL,
    value REAL NOT NULL,
    expected_value REAL,
    prior_period_value REAL,
    prior_period_date TEXT,
    prior_release_value REAL,
    change_vs_prior_period REAL,
    change_vs_prior_release REAL,
    supporting_doc_url TEXT,
    notes TEXT,
    UNIQUE(metric_id, period_date, released_at)
  );
CREATE TABLE source_handles (
    id TEXT PRIMARY KEY,
    platform TEXT NOT NULL DEFAULT 'x',
    handle TEXT NOT NULL,
    display_name TEXT NOT NULL,
    region TEXT,
    role TEXT NOT NULL,
    notes TEXT
  );
CREATE INDEX obs_metric_date_idx ON observations(metric_id, date);
CREATE INDEX calendar_metric_idx ON calendar_events(metric_id);
CREATE INDEX calendar_released_idx ON calendar_events(released_at);
CREATE INDEX release_dispatch_status_idx
        ON release_dispatch_state(status)
      ;
